(function (global) {
  "use strict";
  const EXP_TABLE = new Array(256);
  const LOG_TABLE = new Array(256);
  for (let i = 0; i < 8; i++) EXP_TABLE[i] = 1 << i;
  for (let i = 8; i < 256; i++) EXP_TABLE[i] = EXP_TABLE[i - 4] ^ EXP_TABLE[i - 5] ^ EXP_TABLE[i - 6] ^ EXP_TABLE[i - 8];
  for (let i = 0; i < 255; i++) LOG_TABLE[EXP_TABLE[i]] = i;

  function glog(n) { if (n < 1) throw new Error("glog"); return LOG_TABLE[n]; }
  function gexp(n) { while (n < 0) n += 255; while (n >= 256) n -= 255; return EXP_TABLE[n]; }

  function Poly(num, shift) {
    let offset = 0;
    while (offset < num.length && num[offset] === 0) offset++;
    this.num = new Array(num.length - offset + shift);
    for (let i = 0; i < num.length - offset; i++) this.num[i] = num[i + offset];
  }
  Poly.prototype.get = function (i) { return this.num[i]; };
  Poly.prototype.len = function () { return this.num.length; };
  Poly.prototype.mul = function (e) {
    const n = new Array(this.len() + e.len() - 1).fill(0);
    for (let i = 0; i < this.len(); i++)
      for (let j = 0; j < e.len(); j++)
        n[i + j] ^= gexp(glog(this.get(i)) + glog(e.get(j)));
    return new Poly(n, 0);
  };
  Poly.prototype.mod = function (e) {
    if (this.len() - e.len() < 0) return this;
    const ratio = glog(this.get(0)) - glog(e.get(0));
    const n = this.num.slice();
    for (let i = 0; i < e.len(); i++) n[i] ^= gexp(glog(e.get(i)) + ratio);
    return new Poly(n, 0).mod(e);
  };

  function getErrorCorrectPoly(ecLen) {
    let a = new Poly([1], 0);
    for (let i = 0; i < ecLen; i++) a = a.mul(new Poly([1, gexp(i)], 0));
    return a;
  }

  const RS_BLOCKS_L = {
    1: [[1, 26, 19]], 2: [[1, 44, 34]], 3: [[1, 70, 55]], 4: [[1, 100, 80]], 5: [[1, 134, 108]],
    6: [[2, 86, 68]], 7: [[2, 98, 78]], 8: [[2, 121, 97]], 9: [[2, 146, 116]], 10: [[2, 86, 68], [2, 87, 69]]
  };
  const ALIGN_POS = {
    1: [], 2: [6, 18], 3: [6, 22], 4: [6, 26], 5: [6, 30],
    6: [6, 34], 7: [6, 22, 38], 8: [6, 24, 42], 9: [6, 26, 46], 10: [6, 28, 50]
  };

  function bchDigit(data) { let d = 0; while (data !== 0) { d++; data >>>= 1; } return d; }
  function bchFormatInfo(data) {
    let d = data << 10;
    while (bchDigit(d) - bchDigit(1335) >= 0) d ^= (1335 << (bchDigit(d) - bchDigit(1335)));
    return ((data << 10) | d) ^ 21522;
  }
  function bchTypeNumber(data) {
    let d = data << 12;
    while (bchDigit(d) - bchDigit(7973) >= 0) d ^= (7973 << (bchDigit(d) - bchDigit(7973)));
    return (data << 12) | d;
  }

  function encodeQR(text) {
    const bytes = Array.from(new TextEncoder().encode(text));
    let ver = 1;
    for (; ver <= 10; ver++) {
      const cap = RS_BLOCKS_L[ver].reduce((s, b) => s + b[0] * b[2], 0);
      const headerBytes = ver < 10 ? 2 : 3;
      if (bytes.length + headerBytes <= cap) break;
    }
    if (ver > 10) ver = 10;

    const blocks = [];
    RS_BLOCKS_L[ver].forEach(([cnt, total, data]) => {
      for (let i = 0; i < cnt; i++) blocks.push({ total, data });
    });
    const totalDataBytes = blocks.reduce((s, b) => s + b.data, 0);

    const bits = [];
    function putBits(val, len) { for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1); }
    putBits(4, 4);
    putBits(bytes.length, ver < 10 ? 8 : 16);
    bytes.forEach(b => putBits(b, 8));
    if (bits.length + 4 <= totalDataBytes * 8) putBits(0, 4);
    while (bits.length % 8 !== 0) bits.push(0);
    let padToggle = 0;
    while (bits.length < totalDataBytes * 8) {
      putBits(padToggle % 2 === 0 ? 0xEC : 0x11, 8);
      padToggle++;
    }

    const dataBytes = [];
    for (let i = 0; i < bits.length; i += 8) {
      let b = 0;
      for (let j = 0; j < 8; j++) b = (b << 1) | bits[i + j];
      dataBytes.push(b);
    }

    let offset = 0, maxDc = 0, maxEc = 0;
    const dcData = [], ecData = [];
    blocks.forEach(blk => {
      const dc = dataBytes.slice(offset, offset + blk.data);
      offset += blk.data;
      maxDc = Math.max(maxDc, blk.data);
      const ecLen = blk.total - blk.data;
      maxEc = Math.max(maxEc, ecLen);
      const rsPoly = getErrorCorrectPoly(ecLen);
      const rawPoly = new Poly(dc, rsPoly.len() - 1);
      const modPoly = rawPoly.mod(rsPoly);
      const ec = new Array(ecLen).fill(0);
      for (let i = 0; i < ecLen; i++) {
        const modIdx = i + modPoly.len() - ecLen;
        ec[i] = modIdx >= 0 ? modPoly.get(modIdx) : 0;
      }
      dcData.push(dc);
      ecData.push(ec);
    });

    const codewords = [];
    for (let i = 0; i < maxDc; i++)
      for (let r = 0; r < blocks.length; r++)
        if (i < dcData[r].length) codewords.push(dcData[r][i]);
    for (let i = 0; i < maxEc; i++)
      for (let r = 0; r < blocks.length; r++)
        if (i < ecData[r].length) codewords.push(ecData[r][i]);

    const size = ver * 4 + 17;
    const mod = Array.from({ length: size }, () => new Array(size).fill(null));

    function setProbe(row, col) {
      for (let r = -1; r <= 7; r++) {
        if (row + r < 0 || row + r >= size) continue;
        for (let c = -1; c <= 7; c++) {
          if (col + c < 0 || col + c >= size) continue;
          const dark = (0 <= r && r <= 6 && (c === 0 || c === 6)) ||
                       (0 <= c && c <= 6 && (r === 0 || r === 6)) ||
                       (2 <= r && r <= 4 && 2 <= c && c <= 4);
          mod[row + r][col + c] = dark;
        }
      }
    }
    setProbe(0, 0);
    setProbe(size - 7, 0);
    setProbe(0, size - 7);

    const pos = ALIGN_POS[ver];
    for (let i = 0; i < pos.length; i++) {
      for (let j = 0; j < pos.length; j++) {
        const r0 = pos[i], c0 = pos[j];
        if (mod[r0][c0] !== null) continue;
        for (let r = -2; r <= 2; r++)
          for (let c = -2; c <= 2; c++)
            mod[r0 + r][c0 + c] = (Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0));
      }
    }

    for (let r = 8; r < size - 8; r++) if (mod[r][6] === null) mod[r][6] = (r % 2 === 0);
    for (let c = 8; c < size - 8; c++) if (mod[6][c] === null) mod[6][c] = (c % 2 === 0);

    const fmtBits = bchFormatInfo((1 << 3) | 0);
    for (let i = 0; i < 15; i++) {
      const bit = ((fmtBits >> i) & 1) === 1;
      if (i < 6) mod[i][8] = bit;
      else if (i < 8) mod[i + 1][8] = bit;
      else mod[size - 15 + i][8] = bit;

      if (i < 8) mod[8][size - i - 1] = bit;
      else if (i < 9) mod[8][15 - i] = bit;
      else mod[8][15 - i - 1] = bit;
    }
    mod[size - 8][8] = true;

    if (ver >= 7) {
      const vBits = bchTypeNumber(ver);
      for (let i = 0; i < 18; i++) {
        const bit = ((vBits >> i) & 1) === 1;
        mod[Math.floor(i / 3)][i % 3 + size - 11] = bit;
        mod[i % 3 + size - 11][Math.floor(i / 3)] = bit;
      }
    }

    let inc = -1, row = size - 1, bitIdx = 7, byteIdx = 0;
    for (let col = size - 1; col > 0; col -= 2) {
      if (col === 6) col--;
      while (true) {
        for (let c = 0; c < 2; c++) {
          if (mod[row][col - c] === null) {
            let dark = false;
            if (byteIdx < codewords.length) dark = (((codewords[byteIdx] >>> bitIdx) & 1) === 1);
            if ((row + (col - c)) % 2 === 0) dark = !dark;
            mod[row][col - c] = dark;
            bitIdx--;
            if (bitIdx === -1) { byteIdx++; bitIdx = 7; }
          }
        }
        row += inc;
        if (row < 0 || size <= row) { row -= inc; inc = -inc; break; }
      }
    }
    return { size, mod };
  }

  global.RobotQR = {
    render: function (containerEl, text, pxSize) {
      if (!containerEl) return;
      const sizePx = pxSize || 128;
      const qr = encodeQR(String(text || ""));
      const quiet = 2;
      const cells = qr.size + quiet * 2;
      const scale = Math.max(2, Math.floor(sizePx / cells));
      const canvasSize = cells * scale;

      const canvas = document.createElement("canvas");
      canvas.width = canvasSize;
      canvas.height = canvasSize;
      canvas.style.width = sizePx + "px";
      canvas.style.height = sizePx + "px";
      canvas.style.display = "block";
      canvas.style.imageRendering = "pixelated";

      const ctx = canvas.getContext("2d");
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, canvasSize, canvasSize);
      ctx.fillStyle = "#000000";
      for (let r = 0; r < qr.size; r++) {
        for (let c = 0; c < qr.size; c++) {
          if (qr.mod[r][c]) ctx.fillRect((c + quiet) * scale, (r + quiet) * scale, scale, scale);
        }
      }
      containerEl.innerHTML = "";
      containerEl.appendChild(canvas);
    }
  };
})(window);
